def dec(xi,c,off,khi=7):
    x=torch.tensor(xi); c=torch.tensor(c); B=len(x)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((B,),1-k/20)
            v,A=net.velocity(x,t,c,capture=("blocks.1.act",))
            if off is not None and k<khi:
                m=(A["blocks.1.act"]@W+b)>0
                v=v+m[:,None].float()*torch.tensor(off,dtype=torch.float32)[None]
            x=x-v/20
    return x.numpy()
