import numpy as np, torch, model
net=model.load(); i=9; L="blocks.1.act"; cent=np.load('modecent.npy')
def label(a,cn):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); rad=np.linalg.norm(a,axis=1)
    cc=cent[np.clip((cn*20).astype(int),0,19)]
    return (np.abs(ang-cc)<20)&(rad>1.5)
torch.manual_seed(21); N=20000
xi=torch.randn(N,2); c=torch.rand(N)
a0,S0,A=model.decode(net,xi,c,save_states=True,capture=(L,))
y=label(a0.numpy(),c.numpy()); print('bad mass',y.mean())
res={}
for klo,khi in [(6,11),(4,11)]:
    X=torch.cat([A[L][k] for k in range(klo,khi)]); yt=torch.tensor(np.tile(y,khi-klo)).float()
    mu=X.mean(0); sd=X.std(0)+1e-4
    w=torch.zeros(X.shape[1],requires_grad=True); b=torch.zeros(1,requires_grad=True)
    opt=torch.optim.LBFGS([w,b],max_iter=400)
    def cl():
        opt.zero_grad(); z=((X-mu)/sd)@w+b
        l=torch.nn.functional.binary_cross_entropy_with_logits(z,yt,pos_weight=torch.tensor(2.))+1e-4*(w**2).sum(); l.backward(); return l
    with torch.enable_grad(): opt.step(cl)
    res[(klo,khi)]=((w/sd).detach(),(b-(mu/sd*w).sum()).detach())
orig=net.velocity
torch.manual_seed(7); N2=12000; xi2=torch.randn(N2,2); c2=torch.rand(N2); cn2=c2.numpy()
b0=model.decode(net,xi2,c2).numpy(); y0=label(b0,cn2); ib0=np.asarray(model.in_basin(i,b0))
others=[j for j in range(16) if j!=i]
ob0=np.array([np.asarray(model.in_basin(j,b0)).mean() for j in others])
from scipy.spatial import cKDTree as T
tr=T(np.c_[b0,5*cn2]); d0,_=tr.query(np.c_[b0,5*cn2],k=2)
def run(mode,G,thr,kk):
    dw,db=res[kk]; klo,khi=kk
    def vel(x,t,cc,capture=(),count=False):
        v,a=orig(x,t,cc,tuple(capture)+(L,),count=count)
        k=torch.round((1-t)*20)
        f=((a[L]@dw+db>thr)&(k>=klo)&(k<khi)).float()[:,None]
        if mode=='const': add=torch.tensor([G,0.])[None,:].expand_as(x)
        else: add=G*torch.stack([x[:,1],-x[:,0]],1)  # v -= G*Jx where Jx=(-x1,x0)
        return v+f*add, a
    net.velocity=vel; b1=model.decode(net,xi2,c2).numpy(); net.velocity=orig
    y1=label(b1,cn2)
    drift=((np.linalg.norm(b1-b0,axis=1)>0.3)&~y0).mean()/(~y0).mean()
    ob1=np.array([np.asarray(model.in_basin(j,b1)).mean() for j in others])
    d,_=tr.query(np.c_[b1,5*cn2],k=1)
    return y0.mean(), y1.mean(), drift, (ob1-ob0).max(), (d>0.35).mean()-(d0[:,1]>0.35).mean(), np.asarray(model.in_basin(i,b1)).mean()
