N=4096
xi=torch.randn(N,2); c=torch.rand(N)
def run(delta, K=13, thr=0.0):
    x=xi.clone(); fired=torch.zeros(N)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((N,),1-k/20)
            v,A=net.velocity(x,t,c,capture=("out_act",))
            s=A["out_act"]@w+b
            if k==12: lab=(s>0)
            if delta is not None and k<K:
                m=(s>thr)
                v=v+m[:,None].float()*torch.tensor(delta).float()
                fired+=m.float()
            x=x-v/20
    return x.numpy(), lab.numpy(), fired.numpy()
